class SQLiteSessionStore extends session.Store {
  get(sid, cb) { try { const row=db.prepare('SELECT sess,expire FROM sessions WHERE sid=?').get(sid); if(!row||row.expire<Date.now()){if(row)db.prepare('DELETE FROM sessions WHERE sid=?').run(sid);return cb(null,null)} cb(null,JSON.parse(row.sess)); } catch(e){cb(e)} }
  set(sid,sess,cb=()=>{}) { try { const expire=sess.cookie?.expires?new Date(sess.cookie.expires).getTime():Date.now()+86400000; db.prepare('INSERT INTO sessions(sid,sess,expire) VALUES(?,?,?) ON CONFLICT(sid) DO UPDATE SET sess=excluded.sess,expire=excluded.expire').run(sid,JSON.stringify(sess),expire); cb(); } catch(e){cb(e)} }
  destroy(sid,cb=()=>{}) { try { db.prepare('DELETE FROM sessions WHERE sid=?').run(sid); cb(); } catch(e){cb(e)} }
  touch(sid,sess,cb=()=>{}) { this.set(sid,sess,cb); }
}
