app.use('/api',(req,res,next)=>{if(!firebaseStore)return next();const sendJson=res.json.bind(res);res.json=body=>{if(res.statusCode>=400||res.locals.firebaseUploadQueued)return sendJson(body);const files=[...(req.file?[req.file]:[]),...(Array.isArray(req.files)?req.files:[])];if(!files.length)return sendJson(body);res.locals.firebaseUploadQueued=true;Promise.all(files.map(file=>firebaseStore.storeUpload(file))).then(()=>sendJson(body)).catch(error=>{console.error('Firebase Storage upload failed:',error.message);if(!res.headersSent){res.status(503);sendJson({error:'Cloud file storage is temporarily unavailable. Please retry.'})}});return res};next()});
