const chatUpload=multer({storage:multer.diskStorage({destination:uploadsDir,filename:(_,f,cb)=>cb(null,crypto.randomUUID()+path.extname(f.originalname).toLowerCase())}),limits:{fileSize:25*1024*1024,files:1},fileFilter:(_,f,cb)=>{const ok=/^(image\/(jpeg|png|webp|gif)|video\/(mp4|webm|quicktime)|audio\/(mpeg|mp4|webm|ogg|wav)|application\/(pdf|zip|msword|vnd.openxmlformats-officedocument.wordprocessingml.document)|text\/plain)$/.test(f.mimetype);cb(ok?null:new multer.MulterError('LIMIT_UNEXPECTED_FILE',f.fieldname),ok)}});
