function validImage(file) { const b=fs.readFileSync(file.path); if(file.mimetype==='image/jpeg')return b[0]===0xff&&b[1]===0xd8&&b[2]===0xff; if(file.mimetype==='image/png')return b.subarray(0,8).equals(Buffer.from([137,80,78,71,13,10,26,10])); if(file.mimetype==='image/gif')return b.subarray(0,6).toString()==='GIF87a'||b.subarray(0,6).toString()==='GIF89a'; if(file.mimetype==='image/webp')return b.subarray(0,4).toString()==='RIFF'&&b.subarray(8,12).toString()==='WEBP'; return false; }
