const auth = (req, res, next) => {if(!req.session.user)return res.status(401).json({error:'Please sign in'});if(req.session.user.role==='member'&&!db.prepare('SELECT 1 FROM members WHERE id=? AND active=1').get(req.session.user.member_id)){req.session.destroy(()=>{});return res.status(403).json({error:'This member account is inactive'});}next();};
