function normalizePhone(value){let n=String(value||'').replace(/[\s()-]/g,'');if(/^01[3-9]\d{8}$/.test(n))return '+88'+n;if(/^8801[3-9]\d{8}$/.test(n))return '+'+n;return n;}const totals = (tour, memberId) => { const r = db.prepare('SELECT COALESCE(SUM(amount),0) paid FROM payments WHERE tour_id=? AND member_id=?').get(tour.id, memberId); return r.paid; };

