app.post('/api/register',loginLimit,(req,res)=>{const name=String(req.body.name||'').trim(),phone=normalizePhone(req.body.phone),password=String(req.body.password||'');if(name.length<2||name.length>100||!/^\+?\d{8,15}$/.test(phone)||password.length<6||password.length>128)return res.status(400).json({error:'Enter your name, a valid phone number, and a password with at least 6 characters'});try{db.exec('BEGIN IMMEDIATE');const existing=db.prepare('SELECT id,phone FROM members').all().find(m=>normalizePhone(m.phone)===phone);let memberId;if(existing){if(db.prepare('SELECT 1 FROM users WHERE member_id=?').get(existing.id)){db.exec('ROLLBACK');return res.status(409).json({error:'An account already uses this phone number. Ask an admin for help.'});}memberId=existing.id;db.prepare('UPDATE members SET name=?,phone=?,active=1 WHERE id=?').run(name,phone,memberId);}else memberId=Number(db.prepare('INSERT INTO members(name,phone,active) VALUES(?,?,1)').run(name,phone).lastInsertRowid);db.prepare('INSERT OR IGNORE INTO chat_conversation_members(conversation_id,member_id) VALUES(1,?)').run(memberId);const username='member_'+crypto.randomBytes(12).toString('hex'),account=db.prepare("INSERT INTO users(username,password_hash,role,member_id) VALUES(?,?,'member',?)").run(username,bcrypt.hashSync(password,10),memberId);db.exec('COMMIT');req.session.regenerate(err=>{if(err)return res.status(500).json({error:'Account created. Please sign in.'});req.session.user={id:Number(account.lastInsertRowid),username,role:'member',member_id:memberId};log('Member account created');res.status(201).json({ok:true});});}catch(e){try{db.exec('ROLLBACK')}catch{}res.status(409).json({error:'Could not create this account. Check the phone number and try again.'});}});app.post('/api/login', loginLimit, (req,res)=>{const identity=String(req.body.username||req.body.phone||'').trim(),u=db.prepare('SELECT * FROM users WHERE username=? OR member_id IN (SELECT id FROM members WHERE phone=?) LIMIT 1').get(identity,normalizePhone(identity)); if(!u||!bcrypt.compareSync(req.body.password||'',u.password_hash)) return res.status(401).json({error:'Invalid username or password'}); if(u.role==='member'&&!db.prepare('SELECT 1 FROM members WHERE id=? AND active=1').get(u.member_id))return res.status(403).json({error:'This account is inactive. Contact an administrator.'}); req.session.regenerate(err=>{if(err)return res.status(500).json({error:'Please try again'}); req.session.user={id:u.id,username:u.username,role:u.role,member_id:u.member_id}; res.json({ok:true});});});
