const chatStreams=new Map();const expireChatLocations=()=>db.prepare("UPDATE chat_location_shares SET active=0,latitude=NULL,longitude=NULL WHERE active=1 AND expires_at<=CURRENT_TIMESTAMP").run();const chatLocationExpiryTimer=setInterval(expireChatLocations,60_000);chatLocationExpiryTimer.unref();expireChatLocations();
function chatMemberOf(conversationId,memberId){return !!db.prepare('SELECT 1 FROM chat_conversation_members WHERE conversation_id=? AND member_id=?').get(conversationId,memberId)}
function chatPeerIds(conversationId){return db.prepare('SELECT member_id FROM chat_conversation_members WHERE conversation_id=?').all(conversationId).map(x=>x.member_id)}
function chatEmit(memberIds,event){const packet='data: '+JSON.stringify(event)+'\n\n';for(const id of memberIds)for(const res of chatStreams.get(Number(id))||[])try{res.write(packet)}catch{}}
function chatEmitConversation(conversationId,event){chatEmit(chatPeerIds(conversationId),event)}
function chatMessageData(messageId,viewerId){const m=db.prepare('SELECT c.*,u.name,u.nickname,u.photo FROM chat_messages c JOIN members u ON u.id=c.member_id WHERE c.id=?').get(messageId);if(!m)return null;const attachments=db.prepare('SELECT id,mime,original_name,size FROM chat_attachments WHERE message_id=? ORDER BY id').all(m.id).map(a=>({...a,url:'/api/chat/attachments/'+a.id}));const reactions=db.prepare('SELECT r.emoji,COUNT(*) count,MAX(r.member_id=?) mine FROM chat_reactions r WHERE r.message_id=? GROUP BY r.emoji').all(viewerId,m.id);const receipts=db.prepare('SELECT COUNT(*) delivered,SUM(CASE WHEN read_at IS NOT NULL THEN 1 ELSE 0 END) read FROM chat_receipts WHERE message_id=?').get(m.id);const reply=m.reply_to_id?db.prepare('SELECT c.id,c.body,m.name FROM chat_messages c JOIN members m ON m.id=c.member_id WHERE c.id=?').get(m.reply_to_id):null;const location=m.location_share_id?db.prepare("SELECT id,latitude,longitude,live,active,expires_at FROM chat_location_shares WHERE id=? AND active=1 AND expires_at>CURRENT_TIMESTAMP").get(m.location_share_id):null;return {id:m.id,conversation_id:m.conversation_id,member_id:m.member_id,name:m.name,nickname:m.nickname,photo:m.photo,body:m.deleted_at?'This message was deleted':m.body,kind:m.kind,created_at:m.created_at,edited:!!m.edited_at,deleted:!!m.deleted_at,reply,attachments,reactions,delivered:receipts.delivered||0,read:receipts.read||0,location:location||null}}
app.get('/api/chat/people',auth,(req,res)=>{const uid=req.session.user.member_id;if(!uid)return res.sendStatus(403);const rows=db.prepare('SELECT m.id,m.name,m.photo,COALESCE(p.visible,1) visible,COALESCE(p.online,0) online,p.last_seen,(SELECT c.id FROM chat_conversations c JOIN chat_conversation_members a ON a.conversation_id=c.id AND a.member_id=? JOIN chat_conversation_members b ON b.conversation_id=c.id AND b.member_id=m.id WHERE c.type=\'direct\' LIMIT 1) conversation_id FROM members m LEFT JOIN chat_presence p ON p.member_id=m.id WHERE m.active=1 AND m.id<>? ORDER BY m.name COLLATE NOCASE').all(uid,uid);res.json(rows.map(x=>({...x,online:!!x.visible&&!!x.online,last_seen:x.visible?x.last_seen:null})))});
app.get('/api/chat/stream',auth,(req,res)=>{const id=req.session.user.member_id;if(!id)return res.sendStatus(403);res.status(200).set({'Content-Type':'text/event-stream','Cache-Control':'no-cache, no-transform','Connection':'keep-alive','X-Accel-Buffering':'no'});res.flushHeaders?.();res.write('retry: 2500\n\n');let clients=chatStreams.get(id);if(!clients){clients=new Set();chatStreams.set(id,clients)}clients.add(res);db.prepare('INSERT INTO chat_presence(member_id,online,last_seen) VALUES(?,1,NULL) ON CONFLICT(member_id) DO UPDATE SET online=1').run(id);for(const row of db.prepare('SELECT conversation_id FROM chat_conversation_members WHERE member_id=?').all(id))chatEmit(chatPeerIds(row.conversation_id).filter(x=>x!==id),{type:'presence',memberId:id,online:true});const keep=setInterval(()=>{try{res.write(': keep-alive\n\n')}catch{}},20000);req.on('close',()=>{clearInterval(keep);const set=chatStreams.get(id);set?.delete(res);if(!set?.size){chatStreams.delete(id);db.prepare('INSERT INTO chat_presence(member_id,online,last_seen) VALUES(?,0,CURRENT_TIMESTAMP) ON CONFLICT(member_id) DO UPDATE SET online=0,last_seen=CURRENT_TIMESTAMP').run(id);for(const row of db.prepare('SELECT conversation_id FROM chat_conversation_members WHERE member_id=?').all(id))chatEmit(chatPeerIds(row.conversation_id).filter(x=>x!==id),{type:'presence',memberId:id,online:false,lastSeen:new Date().toISOString()})}})});
app.get('/api/chat/conversations',auth,(req,res)=>{const id=req.session.user.member_id;if(!id)return res.sendStatus(403);db.prepare('INSERT OR IGNORE INTO chat_conversation_members(conversation_id,member_id) SELECT 1,id FROM members WHERE active=1').run();const rows=db.prepare("SELECT c.*, (SELECT body FROM chat_messages x WHERE x.conversation_id=c.id ORDER BY x.id DESC LIMIT 1) last_body,(SELECT id FROM chat_messages x WHERE x.conversation_id=c.id ORDER BY x.id DESC LIMIT 1) last_id,(SELECT created_at FROM chat_messages x WHERE x.conversation_id=c.id ORDER BY x.id DESC LIMIT 1) last_at,(SELECT COUNT(*) FROM chat_messages x WHERE x.conversation_id=c.id AND x.member_id<>? AND NOT EXISTS(SELECT 1 FROM chat_receipts r WHERE r.message_id=x.id AND r.member_id=? AND r.read_at IS NOT NULL)) unread FROM chat_conversations c JOIN chat_conversation_members cm ON cm.conversation_id=c.id WHERE cm.member_id=? ORDER BY COALESCE(last_id,0) DESC,c.id").all(id,id,id);res.json(rows.map(c=>{const members=db.prepare('SELECT m.id,m.name,m.nickname,m.photo,COALESCE(p.visible,1) visible,COALESCE(p.online,0) online,p.last_seen FROM chat_conversation_members cm JOIN members m ON m.id=cm.member_id LEFT JOIN chat_presence p ON p.member_id=m.id WHERE cm.conversation_id=? AND m.id<>?').all(c.id,id);const peer=members[0];return {...c,peer:peer?{...peer,online:!!peer.visible&&!!peer.online,last_seen:peer.visible?peer.last_seen:null}:null,members}}))});
app.post('/api/chat/conversations',auth,(req,res)=>{const me=req.session.user.member_id,type=req.body.type==='group'?'group':'direct';if(type==='direct'){const peer=Number(req.body.memberId);if(!peer||peer===me||!db.prepare('SELECT 1 FROM members WHERE id=? AND active=1').get(peer))return res.status(400).json({error:'Choose an active member'});const found=db.prepare("SELECT c.id FROM chat_conversations c JOIN chat_conversation_members a ON a.conversation_id=c.id AND a.member_id=? JOIN chat_conversation_members b ON b.conversation_id=c.id AND b.member_id=? WHERE c.type='direct' LIMIT 1").get(me,peer);if(found)return res.json({id:found.id});const result=db.prepare("INSERT INTO chat_conversations(type,title,created_by) VALUES('direct','',?)").run(me),id=Number(result.lastInsertRowid);db.prepare('INSERT INTO chat_conversation_members(conversation_id,member_id) VALUES(?,?),(?,?)').run(id,me,id,peer);chatEmit([peer],{type:'conversations'});return res.status(201).json({id})}const title=String(req.body.title||'').trim().slice(0,80),ids=[...new Set([me,...(Array.isArray(req.body.memberIds)?req.body.memberIds:[]).map(Number)])];if(!title||ids.length<3||ids.length>30||ids.some(x=>!db.prepare('SELECT 1 FROM members WHERE id=? AND active=1').get(x)))return res.status(400).json({error:'Enter a group name and choose at least two active members'});const result=db.prepare("INSERT INTO chat_conversations(type,title,created_by) VALUES('group',?,?)").run(title,me),id=Number(result.lastInsertRowid),add=db.prepare('INSERT INTO chat_conversation_members(conversation_id,member_id) VALUES(?,?)');for(const memberId of ids)add.run(id,memberId);chatEmit(ids.filter(x=>x!==me),{type:'conversations'});res.status(201).json({id})});
app.get('/api/chat/conversations/:id/messages',auth,(req,res)=>{const cid=Number(req.params.id),uid=req.session.user.member_id;if(!chatMemberOf(cid,uid))return res.sendStatus(403);const limit=Math.min(50,Math.max(1,Number(req.query.limit)||30)),before=Number(req.query.before)||0,q=String(req.query.q||'').trim().slice(0,100);let rows;if(q)rows=db.prepare('SELECT id FROM chat_messages WHERE conversation_id=? AND body LIKE ? ORDER BY id DESC LIMIT ?').all(cid,'%'+q+'%',limit);else rows=before?db.prepare('SELECT id FROM chat_messages WHERE conversation_id=? AND id<? ORDER BY id DESC LIMIT ?').all(cid,before,limit):db.prepare('SELECT id FROM chat_messages WHERE conversation_id=? ORDER BY id DESC LIMIT ?').all(cid,limit);res.json(rows.reverse().map(x=>chatMessageData(x.id,uid)))});
app.post('/api/chat/conversations/:id/messages',auth,chatActionLimit,(req,res)=>{const cid=Number(req.params.id),uid=req.session.user.member_id,body=String(req.body.body||'').trim(),replyTo=Number(req.body.replyToId)||null;if(!chatMemberOf(cid,uid))return res.sendStatus(403);if(!body||body.length>2000)return res.status(400).json({error:'Enter a message of up to 2,000 characters'});if(replyTo&&!db.prepare('SELECT 1 FROM chat_messages WHERE id=? AND conversation_id=?').get(replyTo,cid))return res.status(400).json({error:'That reply is unavailable'});const r=db.prepare('INSERT INTO chat_messages(conversation_id,member_id,body,reply_to_id) VALUES(?,?,?,?)').run(cid,uid,body,replyTo);const message=chatMessageData(Number(r.lastInsertRowid),uid);chatEmitConversation(cid,{type:'message',message});res.status(201).json(message)});
app.post('/api/chat/conversations/:id/attachments',auth,chatActionLimit,(req,res,next)=>{const cid=Number(req.params.id);if(!chatMemberOf(cid,req.session.user.member_id))return res.sendStatus(403);chatUpload.single('file')(req,res,next)},(req,res)=>{const cid=Number(req.params.id),uid=req.session.user.member_id,f=req.file;if(!f)return res.status(400).json({error:'Choose a file to attach'});const body=String(req.body.caption||'').trim().slice(0,1000);try{const r=db.prepare('INSERT INTO chat_messages(conversation_id,member_id,body,kind) VALUES(?,?,?,?)').run(cid,uid,body,f.mimetype.startsWith('audio/')?'audio':f.mimetype.startsWith('video/')?'video':f.mimetype.startsWith('image/')?'image':'file'),mid=Number(r.lastInsertRowid);db.prepare('INSERT INTO chat_attachments(message_id,filename,original_name,mime,size) VALUES(?,?,?,?,?)').run(mid,f.filename,path.basename(f.originalname).slice(0,180),f.mimetype,f.size);const message=chatMessageData(mid,uid);chatEmitConversation(cid,{type:'message',message});res.status(201).json(message)}catch(e){fs.rmSync(f.path,{force:true});throw e}});
app.get('/api/chat/attachments/:id',auth,async(req,res)=>{const a=db.prepare('SELECT a.*,m.conversation_id FROM chat_attachments a JOIN chat_messages m ON m.id=a.message_id WHERE a.id=?').get(req.params.id);if(!a||!chatMemberOf(a.conversation_id,req.session.user.member_id))return res.sendStatus(404);res.type(a.mime).set('X-Content-Type-Options','nosniff').set('Content-Disposition',`inline; filename="${a.original_name.replace(/["\\\r\n]/g,'_')}"`);if(firebaseStore)return firebaseStore.sendUpload(a.filename,res);res.sendFile(path.join(uploadsDir,path.basename(a.filename)))});
app.post('/api/chat/conversations/:id/read',auth,(req,res)=>{const cid=Number(req.params.id),uid=req.session.user.member_id;if(!chatMemberOf(cid,uid))return res.sendStatus(403);db.prepare("INSERT INTO chat_receipts(message_id,member_id,delivered_at,read_at) SELECT id,?,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM chat_messages WHERE conversation_id=? AND member_id<>? ON CONFLICT(message_id,member_id) DO UPDATE SET delivered_at=COALESCE(delivered_at,CURRENT_TIMESTAMP),read_at=CURRENT_TIMESTAMP").run(uid,cid,uid);chatEmit(chatPeerIds(cid).filter(x=>x!==uid),{type:'receipt',conversationId:cid,memberId:uid});res.json({ok:true})});
