app.post('/api/chat/messages/:id/reactions',auth,(req,res)=>{const mid=Number(req.params.id),uid=req.session.user.member_id,emoji=String(req.body.emoji||'');const m=db.prepare('SELECT conversation_id FROM chat_messages WHERE id=?').get(mid);if(!m||!chatMemberOf(m.conversation_id,uid))return res.sendStatus(403);if(!/^\p{Extended_Pictographic}$/u.test(emoji))return res.status(400).json({error:'Choose one emoji reaction'});const exists=db.prepare('SELECT 1 FROM chat_reactions WHERE message_id=? AND member_id=? AND emoji=?').get(mid,uid,emoji);if(exists)db.prepare('DELETE FROM chat_reactions WHERE message_id=? AND member_id=? AND emoji=?').run(mid,uid,emoji);else db.prepare('INSERT INTO chat_reactions(message_id,member_id,emoji) VALUES(?,?,?)').run(mid,uid,emoji);chatEmitConversation(m.conversation_id,{type:'message-update',message:chatMessageData(mid,uid)});res.json({ok:true})});
app.patch('/api/chat/messages/:id',auth,(req,res)=>{const mid=Number(req.params.id),uid=req.session.user.member_id,body=String(req.body.body||'').trim(),m=db.prepare('SELECT * FROM chat_messages WHERE id=?').get(mid);if(!m||m.member_id!==uid)return res.sendStatus(403);if(!body||body.length>2000||m.deleted_at)return res.status(400).json({error:'Enter a message of up to 2,000 characters'});db.prepare('UPDATE chat_messages SET body=?,edited_at=CURRENT_TIMESTAMP WHERE id=?').run(body,mid);chatEmitConversation(m.conversation_id,{type:'message-update',message:chatMessageData(mid,uid)});res.json({ok:true})});
