app.get('/api/chat/ice-config',auth,(req,res)=>{const servers=[{urls:(process.env.STUN_SERVERS||'stun:stun.l.google.com:19302').split(',').map(x=>x.trim()).filter(Boolean)}];if(process.env.TURN_URLS&&process.env.TURN_SHARED_SECRET){const expires=Math.floor(Date.now()/1000)+3600,username=expires+':'+req.session.user.member_id,credential=crypto.createHmac('sha1',process.env.TURN_SHARED_SECRET).update(username).digest('base64');servers.push({urls:process.env.TURN_URLS.split(',').map(x=>x.trim()).filter(Boolean),username,credential})}res.json({iceServers:servers,turnConfigured:servers.length>1})});
app.post('/api/chat/calls/:callId/signal',auth,chatActionLimit,(req,res)=>{const callId=String(req.params.callId),type=String(req.body.type||''),cid=Number(req.body.conversationId),uid=req.session.user.member_id,allowed=['offer','answer','candidate','reject','hangup'];if(!/^[a-zA-Z0-9-]{12,64}$/.test(callId)||!allowed.includes(type))return res.status(400).json({error:'Invalid call signal'});let call=db.prepare('SELECT * FROM chat_calls WHERE id=?').get(callId);if(type==='offer'){const conv=db.prepare("SELECT id FROM chat_conversations WHERE id=? AND type='direct'").get(cid),peers=chatPeerIds(cid);if(!conv||!peers.includes(uid)||peers.length!==2||call)return res.status(403).json({error:'Calls are available only in a private one-to-one chat'});const peer=peers.find(x=>x!==uid);if(db.prepare("SELECT 1 FROM chat_calls WHERE status='ringing' AND (caller_id=? OR callee_id=?)").get(peer,peer))return res.status(409).json({error:'This member is already on a call'});db.prepare('INSERT INTO chat_calls(id,conversation_id,caller_id,callee_id,mode,status) VALUES(?,?,?,?,?,?)').run(callId,cid,uid,peer,req.body.mode==='video'?'video':'audio','ringing');call=db.prepare('SELECT * FROM chat_calls WHERE id=?').get(callId);}if(!call||![call.caller_id,call.callee_id].includes(uid)||call.conversation_id!==cid)return res.sendStatus(403);const signal=JSON.stringify(req.body.signal||{});if(signal.length>100000)return res.status(413).json({error:'Call signal is too large'});let status=call.status;if(type==='answer'&&uid===call.callee_id){status='accepted';db.prepare("UPDATE chat_calls SET status='accepted',answered_at=CURRENT_TIMESTAMP WHERE id=?").run(callId)}if(type==='reject')status='rejected';if(type==='hangup')status=call.status==='ringing'?'missed':'ended';if(['reject','hangup'].includes(type))db.prepare('UPDATE chat_calls SET status=?,ended_at=CURRENT_TIMESTAMP WHERE id=?').run(status,callId);const peer=uid===call.caller_id?call.callee_id:call.caller_id;chatEmit([peer],{type:'call-signal',callId,conversationId:cid,signalType:type,signal:req.body.signal||{},mode:call.mode,callerId:call.caller_id,memberId:uid,status});res.json({ok:true,status})});
app.get('/api/chat/calls',auth,(req,res)=>{const cid=Number(req.query.conversationId),uid=req.session.user.member_id;if(!chatMemberOf(cid,uid))return res.sendStatus(403);res.json(db.prepare('SELECT c.id,c.mode,c.status,c.created_at,c.answered_at,c.ended_at,m.name peer FROM chat_calls c JOIN members m ON m.id=CASE WHEN c.caller_id=? THEN c.callee_id ELSE c.caller_id END WHERE c.conversation_id=? ORDER BY c.created_at DESC LIMIT 30').all(uid,cid))});
app.post('/api/chat/conversations/:id/location',auth,(req,res)=>{const cid=Number(req.params.id),uid=req.session.user.member_id,lat=Number(req.body.latitude),lon=Number(req.body.longitude),mode=req.body.mode==='live'?'live':'once';if(!chatMemberOf(cid,uid))return res.sendStatus(403);if(!Number.isFinite(lat)||lat < -90||lat>90||!Number.isFinite(lon)||lon < -180||lon>180)return res.status(400).json({error:'Invalid coordinates'});const id=crypto.randomUUID(),minutes=mode==='live'?Math.min(240,Math.max(1,Number(req.body.minutes)||60)):1440,expiry=new Date(Date.now()+minutes*60000).toISOString().replace('T',' ').slice(0,19);db.prepare('INSERT INTO chat_location_shares(id,conversation_id,member_id,latitude,longitude,live,expires_at) VALUES(?,?,?,?,?,?,?)').run(id,cid,uid,lat,lon,mode==='live'?1:0,expiry);const message=db.prepare('INSERT INTO chat_messages(conversation_id,member_id,body,kind,location_share_id) VALUES(?,?,?,"location",?)').run(cid,uid,mode==='live'?'Started live location sharing':'Shared a location',id);const payload=chatMessageData(Number(message.lastInsertRowid),uid);chatEmitConversation(cid,{type:'message',message:payload});res.status(201).json({ok:true,id,message:payload,expires_at:expiry})});
app.post('/api/chat/location/:id/stop',auth,(req,res)=>{const row=db.prepare('SELECT * FROM chat_location_shares WHERE id=?').get(req.params.id),uid=req.session.user.member_id;if(!row||row.member_id!==uid||!row.live)return res.sendStatus(403);db.prepare('UPDATE chat_location_shares SET active=0,latitude=NULL,longitude=NULL WHERE id=?').run(row.id);chatEmitConversation(row.conversation_id,{type:'location-stop',id:row.id});res.json({ok:true})});app.post('/api/chat/location/:id/update',auth,(req,res)=>{const row=db.prepare('SELECT * FROM chat_location_shares WHERE id=?').get(req.params.id),uid=req.session.user.member_id,lat=Number(req.body.latitude),lon=Number(req.body.longitude);if(!row||row.member_id!==uid||!row.live||!row.active||Date.parse(row.expires_at.replace(' ','T')+'Z')<=Date.now())return res.sendStatus(403);if(!Number.isFinite(lat)||lat < -90||lat>90||!Number.isFinite(lon)||lon < -180||lon>180)return res.status(400).json({error:'Invalid coordinates'});db.prepare('UPDATE chat_location_shares SET latitude=?,longitude=? WHERE id=?').run(lat,lon,row.id);chatEmitConversation(row.conversation_id,{type:'location-update',id:row.id,latitude:lat,longitude:lon});res.json({ok:true})});app.get('/api/polls',auth,(req,res)=>{const uid=req.session.user.member_id,rows=db.prepare('SELECT * FROM polls ORDER BY active DESC,id DESC').all();res.json(rows.map(p=>{const options=db.prepare('SELECT o.id,o.label,COUNT(v.member_id) votes FROM poll_options o LEFT JOIN poll_votes v ON v.option_id=o.id WHERE o.poll_id=? GROUP BY o.id ORDER BY o.sort_order,o.id').all(p.id),mine=db.prepare('SELECT option_id FROM poll_votes WHERE poll_id=? AND member_id=?').get(p.id,uid);return {...p,active:!!p.active,canVote:!!p.active&&(!p.ends_at||Date.parse(p.ends_at)>Date.now()),myVote:mine?.option_id||null,total:options.reduce((n,o)=>n+o.votes,0),options}}))});
app.post('/api/polls',auth,admin,(req,res)=>{const title=String(req.body.title||'').trim().slice(0,180),options=[...new Set((Array.isArray(req.body.options)?req.body.options:[]).map(x=>String(x||'').trim()).filter(Boolean))];if(title.length<3||options.length<2||options.length>8||options.some(x=>x.length>120))return res.status(400).json({error:'Add a title and 2–8 options (maximum 120 characters each)'});let endsAt=null;if(req.body.ends_at){const parsedEnd=new Date(req.body.ends_at);if(!Number.isFinite(parsedEnd.getTime()))return res.status(400).json({error:'Choose a valid closing date'});endsAt=parsedEnd.toISOString()}db.exec('BEGIN IMMEDIATE');try{const id=Number(db.prepare('INSERT INTO polls(title,created_by,ends_at) VALUES(?,?,?)').run(title,req.session.user.id,endsAt).lastInsertRowid),add=db.prepare('INSERT INTO poll_options(poll_id,label,sort_order) VALUES(?,?,?)');options.forEach((label,i)=>add.run(id,label,i));db.exec('COMMIT');res.status(201).json({id})}catch(e){db.exec('ROLLBACK');throw e}});
