app.post('/api/albums',auth,(req,res)=>{const uid=req.session.user.member_id,title=String(req.body.title||'').trim(),description=String(req.body.description||'').trim().slice(0,500),visibility=req.body.visibility==='public'?'public':'private';if(!uid)return res.status(403).json({error:'A member profile is required to create an album'});if(title.length<2||title.length>120)return res.status(400).json({error:'Album name must be 2–120 characters'});const id=Number(db.prepare('INSERT INTO albums(tour_id,title,description,owner_member_id,visibility) VALUES(NULL,?,?,?,?)').run(title,description,uid,visibility).lastInsertRowid);res.status(201).json({id})});
app.patch('/api/albums/:id',auth,(req,res)=>{const uid=req.session.user.member_id,a=db.prepare('SELECT * FROM albums WHERE id=?').get(req.params.id);if(!a)return res.sendStatus(404);if(a.owner_member_id!==uid)return res.sendStatus(403);const title=String(req.body.title??a.title).trim(),visibility=req.body.visibility==='public'?'public':'private';if(title.length<2||title.length>120)return res.status(400).json({error:'Album name must be 2–120 characters'});db.prepare('UPDATE albums SET title=?,visibility=? WHERE id=?').run(title,visibility,a.id);res.json({ok:true})});
app.delete('/api/albums/:id',auth,(req,res)=>{const uid=req.session.user.member_id,a=db.prepare('SELECT * FROM albums WHERE id=?').get(req.params.id);if(!a)return res.sendStatus(404);if(a.owner_member_id!==uid)return res.sendStatus(403);const files=db.prepare('SELECT filename FROM media WHERE album_id=?').all(a.id);db.prepare('DELETE FROM media WHERE album_id=?').run(a.id);db.prepare('DELETE FROM albums WHERE id=?').run(a.id);for(const f of files)fs.rmSync(path.join(uploadsDir,path.basename(f.filename)),{force:true});res.json({ok:true})});
app.post('/api/albums/:id/photos',auth,(req,res,next)=>{const uid=req.session.user.member_id,a=db.prepare('SELECT owner_member_id FROM albums WHERE id=?').get(req.params.id);if(!a||a.owner_member_id!==uid)return res.sendStatus(a?403:404);upload.array('photos',10)(req,res,next)},(req,res)=>{const files=req.files||[],uid=req.session.user.member_id,album=db.prepare('SELECT * FROM albums WHERE id=?').get(req.params.id);if(files.length===0)return res.status(400).json({error:'Choose at least one photo'});if(files.some(f=>!validImage(f))){for(const f of files)fs.rmSync(f.path,{force:true});return res.status(400).json({error:'The uploaded image could not be verified'});}let order=db.prepare('SELECT COALESCE(MAX(sort_order),-1)+1 next FROM media WHERE album_id=?').get(album.id).next;const add=db.prepare('INSERT INTO media(album_id,tour_id,member_id,filename,caption,location,taken_at,sort_order) VALUES(?,NULL,?,?,?,?,?,?)');for(const f of files)add.run(album.id,uid,f.filename,String(req.body.caption||'').slice(0,300),String(req.body.location||'').slice(0,200),req.body.taken_at||null,order++);res.status(201).json({ok:true,count:files.length,album_id:album.id})});
app.post('/api/albums/:id/reorder',auth,(req,res)=>{const album=db.prepare('SELECT id,owner_member_id FROM albums WHERE id=?').get(req.params.id),uid=req.session.user.member_id,ids=req.body.photoIds;if(!album)return res.sendStatus(404);if(album.owner_member_id!==uid)return res.sendStatus(403);if(!Array.isArray(ids)||ids.length>1000||ids.some(x=>!Number.isInteger(Number(x))))return res.status(400).json({error:'Invalid photo order'});const existing=db.prepare('SELECT id FROM media WHERE album_id=? ORDER BY sort_order,id DESC').all(album.id).map(x=>x.id);if(ids.length!==existing.length||new Set(ids.map(Number)).size!==existing.length||ids.some(x=>!existing.includes(Number(x))))return res.status(400).json({error:'The photo list has changed. Refresh and try again.'});db.exec('BEGIN IMMEDIATE');try{const update=db.prepare('UPDATE media SET sort_order=? WHERE id=? AND album_id=?');ids.forEach((id,i)=>update.run(i,Number(id),album.id));db.exec('COMMIT');res.json({ok:true})}catch(e){db.exec('ROLLBACK');throw e}});
app.put('/api/media/:id',auth,(req,res)=>{const media=db.prepare('SELECT m.*,a.owner_member_id FROM media m LEFT JOIN albums a ON a.id=m.album_id WHERE m.id=?').get(req.params.id);if(!media)return res.sendStatus(404);if(media.owner_member_id!==req.session.user.member_id&&!(req.session.user.role==='admin'&&media.owner_member_id===null))return res.sendStatus(403);const {caption='',location='',featured=0,taken_at=null}=req.body;db.prepare('UPDATE media SET caption=?,location=?,featured=?,taken_at=? WHERE id=?').run(String(caption).slice(0,300),String(location).slice(0,200),featured?1:0,taken_at||null,req.params.id);res.json({ok:true})});
app.delete('/api/media/:id',auth,(req,res)=>{const media=db.prepare('SELECT m.*,a.owner_member_id FROM media m LEFT JOIN albums a ON a.id=m.album_id WHERE m.id=?').get(req.params.id);if(!media)return res.sendStatus(404);if(media.owner_member_id!==req.session.user.member_id&&!(req.session.user.role==='admin'&&media.owner_member_id===null))return res.sendStatus(403);db.prepare('DELETE FROM media WHERE id=?').run(req.params.id);fs.rmSync(path.join(uploadsDir,path.basename(media.filename)),{force:true});res.json({ok:true})});
app.post('/api/members/:id/photo',auth,admin,upload.single('photo'),(req,res)=>{if(!req.file||!validImage(req.file)){if(req.file)fs.rmSync(req.file.path,{force:true});return res.status(400).json({error:'Choose a valid image file'});}const member=db.prepare('SELECT * FROM members WHERE id=?').get(req.params.id);if(!member){fs.rmSync(req.file.path,{force:true});return res.sendStatus(404);}if(member.photo){const old=db.prepare('SELECT id,filename FROM media WHERE filename=?').get(path.basename(member.photo));if(old){db.prepare('DELETE FROM media WHERE id=?').run(old.id);fs.rmSync(path.join(uploadsDir,old.filename),{force:true});}}db.prepare('UPDATE members SET photo=? WHERE id=?').run('/uploads/'+req.file.filename,req.params.id);db.prepare('INSERT INTO media(member_id,filename,caption) VALUES(?,?,?)').run(req.params.id,req.file.filename,member.name+' profile');res.json({ok:true,photo:'/uploads/'+req.file.filename});});
app.post('/api/settings/:asset',auth,admin,(req,res,next)=>{if(!['logo','hero'].includes(req.params.asset))return res.sendStatus(404);upload.single('image')(req,res,next)},(req,res)=>{const asset=req.params.asset;if(!req.file||!validImage(req.file)){if(req.file)fs.rmSync(req.file.path,{force:true});return res.status(400).json({error:'Choose a valid image file'});}const caption='group '+asset,old=db.prepare('SELECT id,filename FROM media WHERE caption=?').get(caption);if(old){db.prepare('DELETE FROM media WHERE id=?').run(old.id);fs.rmSync(path.join(uploadsDir,old.filename),{force:true});}db.prepare('INSERT INTO media(filename,caption) VALUES(?,?)').run(req.file.filename,caption);db.prepare('INSERT INTO settings(key,value) VALUES(?,?) ON CONFLICT(key) DO UPDATE SET value=excluded.value').run(asset,'/uploads/'+req.file.filename);res.json({ok:true});});
app.get('/uploads/:filename',auth,async(req,res)=>{const row=db.prepare('SELECT x.tour_id,x.member_id,a.owner_member_id,a.visibility FROM media x LEFT JOIN albums a ON a.id=x.album_id WHERE x.filename=?').get(req.params.filename);if(!row)return res.sendStatus(404);const uid=req.session.user.member_id;if(row.owner_member_id!==null&&row.visibility==='private'&&row.owner_member_id!==uid)return res.sendStatus(403);if(row.owner_member_id===null&&req.session.user.role!=='admin'&&row.tour_id!==null&&!db.prepare('SELECT 1 FROM participants WHERE tour_id=? AND member_id=?').get(row.tour_id,uid))return res.sendStatus(403);if(firebaseStore)return firebaseStore.sendUpload(req.params.filename,res);res.sendFile(path.join(uploadsDir,path.basename(req.params.filename)));});
app.get('/api/settings',auth,admin,(req,res)=>res.json(Object.fromEntries(db.prepare('SELECT key,value FROM settings').all().map(x=>[x.key,x.value]))));
app.put('/api/settings',auth,admin,(req,res)=>{const allowed=['group_name','slogan','welcome','support'];const up=db.prepare('INSERT INTO settings(key,value) VALUES(?,?) ON CONFLICT(key) DO UPDATE SET value=excluded.value');for(const k of allowed)if(req.body[k]!==undefined)up.run(k,String(req.body[k]).slice(0,500));log('Group homepage settings updated');res.json({ok:true});});
app.get('/api/export.csv',auth,admin,(req,res)=>{const rows=db.prepare('SELECT p.receipt,p.paid_at,t.title tour,m.name member,p.amount,p.method,p.reference FROM payments p JOIN members m ON m.id=p.member_id JOIN tours t ON t.id=p.tour_id ORDER BY p.id DESC').all();const q=v=>'"'+String(v??'').replaceAll('"','""')+'"';const csv=['Receipt,Date,Tour,Member,Amount BDT,Method,Reference',...rows.map(r=>[r.receipt,r.paid_at,r.tour,r.member,r.amount,r.method,r.reference].map(q).join(','))].join('\r\n');res.type('text/csv').attachment('friends-group-payments.csv').send('\ufeff'+csv);});
app.get('/api/backup',auth,admin,(req,res)=>{const dir=path.join(root,'backups');fs.mkdirSync(dir,{recursive:true});const filename=`friends-${new Date().toISOString().replace(/[:.]/g,'-')}.sqlite`;const target=path.join(dir,filename);db.exec(`VACUUM INTO '${target.replaceAll("'","''")}'`);res.download(target,filename,e=>{if(!e)fs.rmSync(target,{force:true});});});
app.use((err,req,res,next)=>{console.error(err.message);res.status(err instanceof multer.MulterError?400:500).json({error:err instanceof multer.MulterError?(err.code==='LIMIT_FILE_SIZE'?'Keep each photo under 5 MB':'Choose a JPG, PNG, WEBP, or GIF image'):'Something went wrong on the server'});});
const port=Number(process.env.PORT)||3000;const host=process.env.NODE_ENV==='production'?'0.0.0.0':'127.0.0.1';async function startServer(){if(firebaseStore){await firebaseStore.checkConnection();console.log(`Firebase connection verified for ${firebaseProjectId} (${firebaseBucketName})`)}const server=app.listen(port,host,()=>console.log(`Friends Group app ready on ${host}:${port}`));server.on('error',err=>{if(err.code==='EADDRINUSE'){console.error(`Port ${port} is already in use. Stop the other server with Ctrl+C, or start with PORT=${port+1}.`);process.exit(1);}throw err;});}startServer().catch(error=>{console.error('Application startup failed:',error.message);process.exit(1)});



